<template><main class="admin-content" v-if="q"><div class="mb-6 flex flex-wrap items-start justify-between gap-3"><div><NuxtLink to="/admin/manual-quotes" class="text-sm font-bold text-blue-600">← Manual Quotes</NuxtLink><h1 class="mt-2 text-3xl font-black">{{q.quote_number}}</h1><p class="text-slate-500">{{q.sales_customers?.company_name||q.sales_customers?.full_name}}</p></div><div class="flex flex-wrap gap-2"><a :href="`/api/admin/manual-quotes/${q.id}/pdf`" class="btn-secondary">Download PDF</a><button class="btn-secondary" @click="duplicate">Duplicate</button><button class="btn-primary" @click="email">Email Quote</button></div></div><div v-if="msg" class="mb-4 rounded-lg bg-emerald-50 p-3 text-emerald-700">{{msg}}</div><div v-if="err" class="mb-4 rounded-lg bg-red-50 p-3 text-red-700">{{err}}</div>
<section class="admin-panel p-5"><div class="grid gap-4 md:grid-cols-4"><label><span class="label">Customer</span><select v-model="q.customer_id" class="input"><option v-for="c in customers" :value="c.id">{{c.company_name?`${c.company_name} — `:''}}{{c.full_name}}</option></select></label><label><span class="label">Status</span><select v-model="q.status" class="input"><option v-for="s in statuses" :value="s">{{s}}</option></select></label><label><span class="label">Issue Date</span><input v-model="q.issue_date" type="date" class="input"></label><label><span class="label">Valid Until</span><input v-model="q.expires_at" type="date" class="input"></label></div></section>
<section class="admin-panel mt-5 p-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="text-xl font-black">Quote Items</h2><p class="text-sm text-slate-500">Add products from your website or add a manual service/custom item.</p></div><div class="flex gap-2"><button class="btn-secondary" @click="addManual('service')">+ Service</button><button class="btn-secondary" @click="addManual('custom')">+ Custom Item</button></div></div><div class="relative mt-4"><input v-model="productSearch" class="input" placeholder="Search website products to add…" @focus="showProducts=true"><div v-if="showProducts&&filteredProducts.length" class="absolute z-20 mt-1 max-h-72 w-full overflow-auto rounded-lg border bg-white shadow-xl"><button v-for="p in filteredProducts.slice(0,20)" :key="p.id" class="block w-full border-b p-3 text-left hover:bg-blue-50" @click="addProduct(p)"><strong>{{p.name}}</strong><span class="float-right font-bold">{{money(p.price)}}</span><span class="block text-xs text-slate-500">Stock: {{p.stock??0}}</span></button></div></div>
<div class="mt-5 overflow-x-auto"><table class="min-w-[900px] w-full text-sm"><thead><tr class="bg-slate-50 text-left"><th class="p-2">Item</th><th class="p-2">Description / SKU</th><th class="p-2 w-24">Qty</th><th class="p-2 w-36">Unit Price</th><th class="p-2 w-28">Discount %</th><th class="p-2 text-right">Line Total</th><th></th></tr></thead><tbody><tr v-for="(i,n) in q.manual_quote_items" :key="n" class="border-t align-top"><td class="p-2"><input v-model="i.product_name" class="input"></td><td class="p-2"><input v-model="i.description" class="input" placeholder="Description"><input v-model="i.sku" class="input mt-1" placeholder="SKU / code"></td><td class="p-2"><input v-model.number="i.quantity" type="number" min="0.01" step="1" class="input"></td><td class="p-2"><input v-model.number="i.unit_price" type="number" min="0" step="0.01" class="input"></td><td class="p-2"><input v-model.number="i.discount_percent" type="number" min="0" max="100" step="0.01" class="input"></td><td class="p-2 text-right font-bold">{{money(lineTotal(i))}}</td><td class="p-2"><button class="text-red-600" @click="q.manual_quote_items.splice(n,1)">Remove</button></td></tr></tbody></table></div></section>
<section class="mt-5 grid gap-5 lg:grid-cols-[1fr_380px]"><div class="admin-panel p-5"><label><span class="label">Customer Notes / Quote Notes</span><textarea v-model="q.customer_notes" rows="5" class="input" placeholder="Visible on the PDF quote"></textarea></label><label class="mt-4 block"><span class="label">Private Internal Notes</span><textarea v-model="q.internal_notes" rows="4" class="input"></textarea></label></div><div class="admin-panel p-5"><label><span class="label">Delivery Method</span><select v-model="q.delivery_method" class="input"><option value="none">None</option><option value="pickup">Store Pickup</option><option value="delivery">Delivery</option></select></label><label class="mt-3 block"><span class="label">Delivery Amount</span><input v-model.number="q.delivery_amount" type="number" min="0" step="0.01" class="input"></label><label class="mt-3 block"><span class="label">Quote Discount ($)</span><input v-model.number="q.discount_amount" type="number" min="0" step="0.01" class="input"></label><div class="mt-5 space-y-2 border-t pt-4"><div class="flex justify-between"><span>Subtotal</span><strong>{{money(itemsTotal)}}</strong></div><div class="flex justify-between"><span>GST included</span><strong>{{money(total/11)}}</strong></div><div class="flex justify-between text-xl"><span>Total</span><strong>{{money(total)}}</strong></div></div></div></section><div class="sticky bottom-3 mt-6 flex justify-end"><button class="btn-primary shadow-lg" :disabled="saving" @click="save">{{saving?'Saving…':'Save Quote'}}</button></div></main><main v-else class="admin-content">Loading quote…</main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch(),route=useRoute();const q=ref<any>(null),customers=ref<any[]>([]),products=ref<any[]>([]),productSearch=ref(''),showProducts=ref(false),saving=ref(false),msg=ref(''),err=ref('');const statuses=['draft','sent','accepted','declined','expired','converted'];const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const lineTotal=(i:any)=>Number(i.quantity||0)*Number(i.unit_price||0)*(1-Number(i.discount_percent||0)/100);const itemsTotal=computed(()=>q.value?.manual_quote_items?.reduce((s:number,i:any)=>s+lineTotal(i),0)||0);const total=computed(()=>Math.max(0,itemsTotal.value+Number(q.value?.delivery_amount||0)-Number(q.value?.discount_amount||0)));const filteredProducts=computed(()=>{const x=productSearch.value.trim().toLowerCase();return x?products.value.filter((p:any)=>`${p.name} ${p.slug||''} ${p.sku||''}`.toLowerCase().includes(x)):[]});async function load(){[q.value,customers.value,products.value]=await Promise.all([adminFetch(`/api/admin/manual-quotes/${route.params.id}`),adminFetch('/api/admin/customers'),adminFetch('/api/admin/products')]) as any}function addProduct(p:any){q.value.manual_quote_items.push({product_id:p.id,item_type:'product',product_name:p.name,description:'',sku:p.sku||'',quantity:1,unit_price:Number(p.price||0),discount_percent:0});productSearch.value='';showProducts.value=false}function addManual(type:string){q.value.manual_quote_items.push({product_id:null,item_type:type,product_name:type==='service'?'Service / Labour':'Custom Item',description:'',sku:'',quantity:1,unit_price:0,discount_percent:0})}async function save(){saving.value=true;err.value='';try{q.value=await adminFetch(`/api/admin/manual-quotes/${q.value.id}`,{method:'PUT',body:{...q.value,items:q.value.manual_quote_items}});msg.value='Quote saved.'}catch(e:any){err.value=e?.data?.statusMessage||e.message}finally{saving.value=false}}async function email(){await save();try{await adminFetch(`/api/admin/manual-quotes/${q.value.id}/email`,{method:'POST'});q.value.status='sent';msg.value='Quote PDF emailed to the customer.'}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function duplicate(){const x:any=await adminFetch(`/api/admin/manual-quotes/${q.value.id}/duplicate`,{method:'POST'});await navigateTo(`/admin/manual-quotes/${x.id}`)}onMounted(load)</script><style scoped>.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm}.label{@apply mb-1 block text-sm font-bold text-slate-700}.btn-primary{@apply rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-bold text-white hover:bg-blue-700 disabled:opacity-50}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm font-bold text-slate-700 hover:bg-slate-50}.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}</style>
